74	/**
75	 * CRM Component
76	 *
77	 * This component sets up and renders the main CRM application using `ra-core`. It provides
78	 * default configurations and themes but allows for customization through props. The component
79	 * seeds the store with any custom prop values for backwards compatibility.
80	 *
81	 * @param {LabeledValue[]} companySectors - The list of company sectors used in the application.
82	 * @param {string} currency - The ISO 4217 currency code used to format monetary values (e.g. "USD", "EUR", "GBP").
83	 * @param {RaThemeOptions} darkTheme - The theme to use when the application is in dark mode.
84	 * @param {LabeledValue[]} dealCategories - The categories of deals used in the application.
85	 * @param {string[]} dealPipelineStatuses - The statuses of deals in the pipeline used in the application.
86	 * @param {DealStage[]} dealStages - The stages of deals used in the application.
87	 * @param {RaThemeOptions} lightTheme - The theme to use when the application is in light mode.
88	 * @param {string} logo - The logo used in the CRM application.
89	 * @param {NoteStatus[]} noteStatuses - The statuses of notes used in the application.
90	 * @param {LabeledValue[]} taskTypes - The types of tasks used in the application.
91	 * @param {string} title - The title of the CRM application.
92	 *
93	 * @returns {JSX.Element} The rendered CRM application.
94	 *
95	 * @example
96	 * // Basic usage of the CRM component
97	 * import { CRM } from '@/components/atomic-crm/dashboard/CRM';
98	 *
99	 * const App = () => (
100	 *     <CRM
101	 *         logo="/path/to/logo.png"
102	 *         title="My Custom CRM"
103	 *         lightTheme={{
104	 *             ...defaultTheme,
105	 *             palette: {
106	 *                 primary: { main: '#0000ff' },
107	 *             },
108	 *         }}
109	 *     />
110	 * );
111	 *
112	 * export default App;
113	 */
114	export const CRM = ({
115	  companySectors = defaultCompanySectors,
116	  currency = defaultCurrency,
117	  dealCategories = defaultDealCategories,
118	  dealPipelineStatuses = defaultDealPipelineStatuses,
119	  dealStages = defaultDealStages,
120	  darkModeLogo = defaultDarkModeLogo,
121	  lightModeLogo = defaultLightModeLogo,
122	  noteStatuses = defaultNoteStatuses,
123	  taskTypes = defaultTaskTypes,
124	  title = defaultTitle,
125	  dataProvider = defaultDataProviderBuilder(),
126	  authProvider = defaultAuthProviderBuilder(),
127	  i18nProvider = defaulti18nProvider,
128	  store = defaultStore,
129	  googleWorkplaceDomain = import.meta.env.VITE_GOOGLE_WORKPLACE_DOMAIN,
130	  disableEmailPasswordAuthentication = import.meta.env
131	    .VITE_DISABLE_EMAIL_PASSWORD_AUTHENTICATION === "true",
132	  disableTelemetry,
133	  ...rest
134	}: CRMProps) => {
135	  useEffect(() => {
136	    if (
137	      disableTelemetry ||
138	      process.env.NODE_ENV !== "production" ||
139	      typeof window === "undefined" ||
140	      typeof window.location === "undefined" ||
141	      typeof Image === "undefined"
142	    ) {
143	      return;
144	    }
145	    const img = new Image();
146	    img.src = `https://atomic-crm-telemetry.marmelab.com/atomic-crm-telemetry?domain=${window.location.hostname}`;
147	  }, [disableTelemetry]);
148	
149	  // Seed the store with CRM prop values if not already stored
150	  // (backwards compatibility for prop-based config)
151	  useEffect(() => {
152	    if (!store.getItem(CONFIGURATION_STORE_KEY)) {
153	      store.setItem(CONFIGURATION_STORE_KEY, {
154	        companySectors,
155	        currency,
156	        dealCategories,
157	        dealPipelineStatuses,
158	        dealStages,
159	        noteStatuses,
160	        taskTypes,
161	        title,
162	        darkModeLogo,
163	        lightModeLogo,
164	        googleWorkplaceDomain,
165	        disableEmailPasswordAuthentication,
166	      } satisfies ConfigurationContextValue);
167	    }
168	    // eslint-disable-next-line react-hooks/exhaustive-deps
169	  }, [store]);
170	
171	  const isMobile = useIsMobile();
172	
173	  // on login, pre-fetch the configuration to avoid a flickering
174	  // when accessing the app for the first time
175	  const wrappedAuthProvider = useMemo<AuthProvider>(
176	    () => ({
177	      ...authProvider,
178	      login: async (params: any) => {
179	        const result = await authProvider.login(params);
180	        try {
181	          const config = await dataProvider.getConfiguration();
182	          if (Object.keys(config).length > 0) {
183	            store.setItem(CONFIGURATION_STORE_KEY, config);
184	          }
185	        } catch {
186	          // Non-critical: config will load via useConfigurationLoader
187	        }
188	        return result;
189	      },
190	      handleCallback: async (params: any) => {
191	        if (!authProvider.handleCallback) {
192	          throw new Error(
193	            "handleCallback is not implemented in the authProvider",
194	          );
195	        }
196	        const result = await authProvider.handleCallback(params);
197	        try {
198	          const config = await dataProvider.getConfiguration();
199	          if (Object.keys(config).length > 0) {
200	            store.setItem(CONFIGURATION_STORE_KEY, config);
201	          }
202	        } catch {
203	          // Non-critical: config will load via useConfigurationLoader
204	        }
205	        return result;
206	      },
207	      logout: async (params: any) => {
208	        try {
209	          store.removeItem(CONFIGURATION_STORE_KEY);
210	        } catch {
211	          // Ignore
212	        }
213	        return authProvider.logout(params);
214	      },
215	    }),
216	    [authProvider, dataProvider, store],
217	  );
218	
219	  const ResponsiveAdmin = isMobile ? MobileAdmin : DesktopAdmin;
220	
221	  return (
222	    <ResponsiveAdmin
223	      dataProvider={dataProvider}
224	      authProvider={wrappedAuthProvider}
225	      i18nProvider={i18nProvider}
226	      store={store}
227	      loginPage={StartPage}
228	      requireAuth
229	      disableTelemetry
230	      {...rest}
231	    />
232	  );
233	};
