235	const DesktopAdmin = (
236	  props: CoreAdminProps & {
237	    dashboard?: DashboardComponent;
238	    layout?: LayoutComponent;
239	  },
240	) => {
241	  return (
242	    <Admin
243	      layout={props.layout ?? Layout}
244	      dashboard={props.dashboard ?? Dashboard}
245	      {...props}
246	    >
247	      <CustomRoutes noLayout>
248	        <Route path={SignupPage.path} element={<SignupPage />} />
249	        <Route
250	          path={ConfirmationRequired.path}
251	          element={<ConfirmationRequired />}
252	        />
253	        <Route path={SetPasswordPage.path} element={<SetPasswordPage />} />
254	        <Route
255	          path={ForgotPasswordPage.path}
256	          element={<ForgotPasswordPage />}
257	        />
258	        <Route path={OAuthConsentPage.path} element={<OAuthConsentPage />} />
259	      </CustomRoutes>
260	
261	      <CustomRoutes>
262	        <Route path={ProfilePage.path} element={<ProfilePage />} />
263	        <Route path={SettingsPage.path} element={<SettingsPage />} />
264	        <Route path={ImportPage.path} element={<ImportPage />} />
265	      </CustomRoutes>
266	      <Resource name="deals" {...deals} />
267	      <Resource name="contacts" {...contacts} />
268	      <Resource name="companies" {...companies} />
269	      <Resource name="contact_notes" />
270	      <Resource name="deal_notes" />
271	      <Resource name="tasks" />
272	      <Resource name="sales" {...sales} />
273	      <Resource name="tags" />
274	    </Admin>
275	  );
276	};
277	
278	const MobileAdmin = (
279	  props: CoreAdminProps & {
280	    dashboard?: DashboardComponent;
281	    layout?: LayoutComponent;
282	  },
283	) => {
284	  const queryClient = new QueryClient({
285	    defaultOptions: {
286	      queries: {
287	        gcTime: 1000 * 60 * 60 * 24, // 24 hours
288	        networkMode: "offlineFirst",
289	      },
290	      mutations: {
291	        networkMode: "offlineFirst",
292	      },
293	    },
294	  });
295	  const asyncStoragePersister = createAsyncStoragePersister({
296	    storage: localStorage,
297	  });
298	
299	  return (
300	    <PersistQueryClientProvider
301	      client={queryClient}
302	      persistOptions={{ persister: asyncStoragePersister }}
303	    >
304	      <Admin
305	        queryClient={queryClient}
306	        layout={props.layout ?? MobileLayout}
307	        dashboard={props.dashboard ?? MobileDashboard}
308	        {...props}
309	      >
310	        <CustomRoutes noLayout>
311	          <Route path={SignupPage.path} element={<SignupPage />} />
312	          <Route
313	            path={ConfirmationRequired.path}
314	            element={<ConfirmationRequired />}
315	          />
316	          <Route path={SetPasswordPage.path} element={<SetPasswordPage />} />
317	          <Route
318	            path={ForgotPasswordPage.path}
319	            element={<ForgotPasswordPage />}
320	          />
321	          <Route path={OAuthConsentPage.path} element={<OAuthConsentPage />} />
322	        </CustomRoutes>
323	        <CustomRoutes>
324	          <Route
325	            path={SettingsPageMobile.path}
326	            element={<SettingsPageMobile />}
327	          />
328	        </CustomRoutes>
329	        <Resource
330	          name="contacts"
331	          list={ContactListMobile}
332	          show={ContactShow}
333	          recordRepresentation={contacts.recordRepresentation}
334	        >
335	          <Route path=":id/notes/:noteId" element={<NoteShowPage />} />
336	        </Resource>
337	        <Resource name="companies" show={CompanyShow} />
338	        <Resource name="tasks" list={MobileTasksList} />
339	      </Admin>
340	    </PersistQueryClientProvider>
341	  );
342	};
