14	    const company = random.arrayElement(db.companies);
15	    company.nb_deals = (company.nb_deals ?? 0) + 1;
16	    const contacts = random.arrayElements(
17	      db.contacts.filter((contact) => contact.company_id === company.id),
18	      datatype.number({ min: 1, max: 3 }),
19	    );
20	    const lowercaseName = lorem.words();
21	    const created_at = randomDate(new Date(company.created_at)).toISOString();
22	
23	    const expected_closing_date = randomDate(
24	      new Date(created_at),
25	      add(new Date(created_at), { months: 6 }),
26	    )
27	      .toISOString()
28	      .split("T")[0];
29	
30	    return {
31	      id,
32	      name: lowercaseName[0].toUpperCase() + lowercaseName.slice(1),
33	      company_id: company.id,
34	      contact_ids: contacts.map((contact) => contact.id),
35	      category: random.arrayElement(defaultDealCategories).value,
36	      stage: random.arrayElement(defaultDealStages).value,
37	      description: lorem.paragraphs(datatype.number({ min: 1, max: 4 })),
38	      amount: datatype.number(1000) * 100,
39	      created_at,
