26	export const ContactListContent = () => {
27	  const translate = useTranslate();
28	  const {
29	    data: contacts,
30	    error,
31	    isPending,
32	    onToggleItem,
33	    onSelect,
34	    selectedIds,
35	  } = useListContext<Contact>();
36	  const lastSelected = useRef<Identifier | null>(null);
37	
38	  // Handle shift+click to select a range of rows
39	  const handleToggleItem = useCallback(
40	    (id: Identifier, event: MouseEvent) => {
41	      if (!contacts) return;
42	
43	      const ids = contacts.map((contact) => contact.id);
44	      const lastSelectedIndex = lastSelected.current
45	        ? ids.indexOf(lastSelected.current)
46	        : -1;
47	
48	      if (event.shiftKey && lastSelectedIndex !== -1) {
49	        const index = ids.indexOf(id);
50	        const idsBetweenSelections = ids.slice(
51	          Math.min(lastSelectedIndex, index),
52	          Math.max(lastSelectedIndex, index) + 1,
53	        );
54	
55	        const isClickedItemSelected = selectedIds?.includes(id);
56	        const newSelectedIds = isClickedItemSelected
57	          ? difference(selectedIds, idsBetweenSelections)
58	          : union(selectedIds, idsBetweenSelections);
59	
60	        onSelect?.(newSelectedIds);
61	      } else {
62	        onToggleItem(id);
63	      }
64	
65	      lastSelected.current = id;
66	    },
67	    [contacts, selectedIds, onSelect, onToggleItem],
68	  );
69	
70	  if (isPending) {
71	    return <Skeleton className="w-full h-9" />;
72	  }
73	
74	  if (error) {
75	    return null;
76	  }
