3	export const weightedArrayElement = (values: any[], weights: any) =>
4	  faker.random.arrayElement(
5	    values.reduce(
6	      (acc, value, index) => acc.concat(new Array(weights[index]).fill(value)),
7	      [],
8	    ),
9	  );
10	
11	export const weightedBoolean = (likelyhood: number) =>
12	  faker.datatype.number(99) < likelyhood;
13	
14	export const randomDate = (minDate?: Date, maxDate?: Date) => {
15	  const minTs =
16	    minDate instanceof Date
17	      ? minDate.getTime()
18	      : Date.now() - 5 * 365 * 24 * 60 * 60 * 1000; // 5 years
19	  const maxTs = maxDate instanceof Date ? maxDate.getTime() : Date.now();
20	  const range = maxTs - minTs;
21	  const randomRange = faker.datatype.number({ max: range });
22	  // move it more towards today to account for traffic increase
23	  const ts = Math.sqrt(randomRange / range) * range;
24	  return new Date(minTs + ts);
25	};
