/**
 * A contact is considered "new" when its `first_seen` date is within
 * this many days of the current date. Used by {@link NewContactBadge}.
 */
const NEW_CONTACT_THRESHOLD_DAYS = 7;
const NEW_CONTACT_THRESHOLD_MS =
  NEW_CONTACT_THRESHOLD_DAYS * 24 * 60 * 60 * 1000;

/**
 * Returns `true` when the given ISO date string is a valid date less
 * than {@link NEW_CONTACT_THRESHOLD_DAYS} days before `now`.
 *
 * Safe on `null`/`undefined`/malformed inputs — returns `false`.
 */
const isRecentFirstSeen = (
  firstSeen: string | null | undefined,
  now: number = Date.now(),
): boolean => {
  if (!firstSeen) return false;
  const ts = Date.parse(firstSeen);
  if (Number.isNaN(ts)) return false;
  return now - ts < NEW_CONTACT_THRESHOLD_MS;
};

/**
 * Renders a "New" badge when the contact's `first_seen` is within the
 * last {@link NEW_CONTACT_THRESHOLD_DAYS} days. Renders nothing
 * otherwise, so older or unknown-date contacts cause no layout shift.
 */
const NewContactBadge = ({ firstSeen }: { firstSeen?: string | null }) => {
  if (!isRecentFirstSeen(firstSeen)) return null;
  return (
    <Badge
      variant="secondary"
      aria-label="New contact"
      data-testid="new-contact-badge"
    >
      New
    </Badge>
  );
};

