import type { Db } from "./types";

export const finalize = (db: Db) => {
  // set contact status according to the latest note
  db.contact_notes
    .sort((a, b) => new Date(a.date).valueOf() - new Date(b.date).valueOf())
    .forEach((note) => {
      db.contacts[note.contact_id as number].status = note.status;
    });

  // Denormalize nb_notes onto each deal so the Kanban card can display a
  // note counter without running a separate query per card.
  // Initialize every deal to 0 first so deals with no notes still report a
  // known value (rather than undefined) while honoring the optional type.
  db.deals.forEach((deal) => {
    deal.nb_notes = 0;
  });
  db.deal_notes.forEach((note) => {
    const deal = db.deals[note.deal_id as number];
    if (deal) {
      deal.nb_notes = (deal.nb_notes ?? 0) + 1;
    }
  });
};

const maxContacts = {
  1: 1,
  10: 4,
  50: 12,
  250: 25,
  500: 50,
};

/**
 * Number of generated contacts that should be marked as "recently
 * seen" (i.e. `first_seen` within the last 7 days), so the "New"
 * badge is visible when the demo data loads.
 */
const NUMBER_OF_RECENT_CONTACTS = 5;
const SEVEN_DAYS_MS = 7 * 24 * 60 * 60 * 1000;

/**
 * Returns a random ISO date between `now - 7 days + 1 hour` (to stay
 * strictly within the "new" window) and `now`.
 */
const randomRecentDate = (): string => {
  const now = Date.now();
  // Stay at least 1 hour inside the window to avoid off-by-one flakiness.
  const minTs = now - SEVEN_DAYS_MS + 60 * 60 * 1000;
  const ts = minTs + Math.floor(Math.random() * (now - minTs));
  return new Date(ts).toISOString();
};

// Force the first few contacts to have a recent `first_seen` so
// the "New" badge is visible in demo mode. Older IDs still get a
// random date in the company's history.
const first_seen =
  id < NUMBER_OF_RECENT_CONTACTS
