97	      id < NUMBER_OF_RECENT_CONTACTS
98	        ? randomRecentDate()
99	        : randomDate(new Date(company.created_at)).toISOString();
100	    const last_seen = first_seen;
101	
102	    return {
103	      id,
104	      first_name,
105	      last_name,
106	      gender,
107	      title: title.charAt(0).toUpperCase() + title.substr(1),
108	      company_id: company.id,
109	      company_name: company.name,
110	      email_jsonb,
111	      phone_jsonb,
112	      background: lorem.sentence(),
