import { describe, expect, it } from "vitest";

import { finalize } from "./finalize";
import type { Db } from "./types";
import type {
  Contact,
  ContactNote,
  Deal,
  DealNote,
} from "../../../types";

/**
 * Builds a minimal `Db` shape with just the slices the finalize function
 * touches. Other collections default to empty arrays to keep the test
 * focused on the behavior under test.
 */
const buildDb = (partial: {
  deals?: Deal[];
  deal_notes?: DealNote[];
  contacts?: Contact[];
  contact_notes?: ContactNote[];
}): Db => ({
  companies: [],
  contacts: partial.contacts ?? [],
  contact_notes: partial.contact_notes ?? [],
  deals: partial.deals ?? [],
  deal_notes: partial.deal_notes ?? [],
  sales: [],
  tags: [],
  tasks: [],
  configuration: [],
});

const makeDeal = (id: number): Deal => ({
  id,
  name: `Deal ${id}`,
  company_id: 0,
  contact_ids: [],
  category: "",
  stage: "opportunity",
  description: "",
  amount: 0,
  created_at: "2025-01-01T00:00:00.000Z",
  updated_at: "2025-01-01T00:00:00.000Z",
  expected_closing_date: "2025-02-01",
  sales_id: 0,
  index: 0,
});

const makeDealNote = (id: number, dealId: number): DealNote => ({
  id,
  deal_id: dealId,
  text: "note body",
  date: "2025-01-02T00:00:00.000Z",
  sales_id: 0,
});

describe("finalize — nb_notes denormalization", () => {
  it("sets nb_notes to the count of deal_notes per deal", () => {
    // Arrange
    const deals = [makeDeal(0), makeDeal(1), makeDeal(2)];
    const deal_notes = [
      makeDealNote(0, 0),
      makeDealNote(1, 0),
      makeDealNote(2, 0),
      makeDealNote(3, 1),
    ];
    const db = buildDb({ deals, deal_notes });

    // Act
    finalize(db);

    // Assert
    expect(db.deals[0].nb_notes).toBe(3);
    expect(db.deals[1].nb_notes).toBe(1);
    expect(db.deals[2].nb_notes).toBe(0);
  });

  it("initializes nb_notes to 0 for deals with no matching notes", () => {
    // Arrange
    const deals = [makeDeal(0), makeDeal(1)];
    const db = buildDb({ deals, deal_notes: [] });

    // Act
    finalize(db);

    // Assert
    expect(db.deals[0].nb_notes).toBe(0);
    expect(db.deals[1].nb_notes).toBe(0);
  });

  it("does not mutate the original deal_notes array", () => {
    // Arrange
    const deals = [makeDeal(0)];
    const deal_notes = [makeDealNote(0, 0), makeDealNote(1, 0)];
    const originalLength = deal_notes.length;
    const db = buildDb({ deals, deal_notes });

    // Act
    finalize(db);

    // Assert
    expect(db.deal_notes).toHaveLength(originalLength);
    expect(db.deals[0].nb_notes).toBe(2);
  });

  it("ignores notes whose deal_id does not resolve to an existing deal", () => {
    // Arrange — note pointing to a deal that does not exist
    const deals = [makeDeal(0)];
    const deal_notes = [makeDealNote(0, 0), makeDealNote(1, 99)];
    const db = buildDb({ deals, deal_notes });

    // Act
    finalize(db);

    // Assert — only the valid note is counted, no crash
    expect(db.deals[0].nb_notes).toBe(1);
  });
});

import { test, expect } from "./fixtures";

/**
 * TASK-003 — verify that the "New" badge is rendered on contact list
 * rows whose `first_seen` is within the last 7 days, and is absent on
 * older contacts.
 */
test("shows the 'New' badge only on contacts seen within the last 7 days", async ({
  page,
  createContact,
  createSales,
  menu,
}) => {
  const sales = await createSales({
    email: "john@doe.com",
    first_name: "John",
    last_name: "Doe",
    password: "password",
  });

  // Recent contact — first_seen is now, should show the badge.
  await createContact({
    first_name: "Recent",
    last_name: "Contact",
    sales_id: sales.id,
    first_seen: new Date().toISOString(),
  });

  // Old contact — first_seen is 30 days ago, should NOT show the badge.
  const thirtyDaysAgo = new Date(
    Date.now() - 30 * 24 * 60 * 60 * 1000,
  ).toISOString();
  await createContact({
    first_name: "Old",
    last_name: "Contact",
    sales_id: sales.id,
    first_seen: thirtyDaysAgo,
  });

  await page.goto("http://localhost:5175/");

  await page.getByLabel("Email").fill("john@doe.com");
  await page.getByLabel("Password").fill("password");
  await page.getByRole("button", { name: "Sign in" }).click();

  await expect(page).toHaveTitle(/Atomic CRM/);
  await menu.goToContacts();

  // Both contacts should be visible in the list before we assert on the badge.
  await expect(page.getByText("Recent Contact")).toBeVisible();
  await expect(page.getByText("Old Contact")).toBeVisible();

  // Exactly one "New" badge should be present in the list — the one
  // belonging to the recent contact.
  const newBadges = page.getByTestId("new-contact-badge");
  await expect(newBadges).toHaveCount(1);

  // The visible "New" badge should sit next to "Recent Contact", not
  // "Old Contact". Scope the locator to the row containing each name.
  await expect(
    page
      .locator("a", { hasText: "Recent Contact" })
      .getByTestId("new-contact-badge"),
  ).toBeVisible();
  await expect(
    page
      .locator("a", { hasText: "Old Contact" })
      .getByTestId("new-contact-badge"),
  ).toHaveCount(0);
});

