27	/**
28	 * A contact is considered "new" when its `first_seen` date is within
29	 * this many days of the current date. Used by {@link NewContactBadge}.
30	 */
31	const NEW_CONTACT_THRESHOLD_DAYS = 7;
32	const NEW_CONTACT_THRESHOLD_MS =
33	  NEW_CONTACT_THRESHOLD_DAYS * 24 * 60 * 60 * 1000;
34	
35	/**
36	 * Returns `true` when the given ISO date string is a valid date less
37	 * than {@link NEW_CONTACT_THRESHOLD_DAYS} days before `now`.
38	 *
39	 * Safe on `null`/`undefined`/malformed inputs — returns `false`.
40	 */
41	const isRecentFirstSeen = (
42	  firstSeen: string | null | undefined,
43	  now: number = Date.now(),
44	): boolean => {
45	  if (!firstSeen) return false;
46	  const ts = Date.parse(firstSeen);
47	  if (Number.isNaN(ts)) return false;
48	  return now - ts < NEW_CONTACT_THRESHOLD_MS;
49	};
