77	    selectedIds,
78	  } = useListContext<Contact>();
79	  const lastSelected = useRef<Identifier | null>(null);
80	
81	  // Handle shift+click to select a range of rows
82	  const handleToggleItem = useCallback(
83	    (id: Identifier, event: MouseEvent) => {
84	      if (!contacts) return;
85	
86	      const ids = contacts.map((contact) => contact.id);
87	      const lastSelectedIndex = lastSelected.current
88	        ? ids.indexOf(lastSelected.current)
89	        : -1;
90	
91	      if (event.shiftKey && lastSelectedIndex !== -1) {
92	        const index = ids.indexOf(id);
93	        const idsBetweenSelections = ids.slice(
94	          Math.min(lastSelectedIndex, index),
95	          Math.max(lastSelectedIndex, index) + 1,
96	        );
97	
98	        const isClickedItemSelected = selectedIds?.includes(id);
99	        const newSelectedIds = isClickedItemSelected
100	          ? difference(selectedIds, idsBetweenSelections)
101	          : union(selectedIds, idsBetweenSelections);
102	
103	        onSelect?.(newSelectedIds);
104	      } else {
105	        onToggleItem(id);
106	      }
107	
108	      lastSelected.current = id;
109	    },
110	    [contacts, selectedIds, onSelect, onToggleItem],
111	  );
