1	import {
2	  company as fakerCompany,
3	  internet,
4	  lorem,
5	  name,
6	  phone,
7	  random,
8	} from "faker/locale/en_US";
9	
10	import { defaultNoteStatuses } from "../../../root/defaultConfiguration";
11	import { contactGender } from "../../../contacts/contactModel";
12	import type { Company, Contact } from "../../../types";
13	import type { Db } from "./types";
14	import { randomDate, weightedBoolean } from "./utils";
15	
16	const maxContacts = {
17	  1: 1,
18	  10: 4,
19	  50: 12,
20	  250: 25,
21	  500: 50,
22	};
23	
24	/**
25	 * Number of generated contacts that should be marked as "recently
26	 * seen" (i.e. `first_seen` within the last 7 days), so the "New"
27	 * badge is visible when the demo data loads.
28	 */
29	const NUMBER_OF_RECENT_CONTACTS = 5;
30	const SEVEN_DAYS_MS = 7 * 24 * 60 * 60 * 1000;
31	
32	/**
33	 * Returns a random ISO date between `now - 7 days + 1 hour` (to stay
34	 * strictly within the "new" window) and `now`.
35	 */
36	const randomRecentDate = (): string => {
37	  const now = Date.now();
38	  // Stay at least 1 hour inside the window to avoid off-by-one flakiness.
39	  const minTs = now - SEVEN_DAYS_MS + 60 * 60 * 1000;
40	  const ts = minTs + Math.floor(Math.random() * (now - minTs));
41	  return new Date(ts).toISOString();
42	};
43	
44	const getRandomContactDetailsType = () =>
45	  random.arrayElement(["Work", "Home", "Other"]) as "Work" | "Home" | "Other";
46	
47	export const generateContacts = (db: Db, size = 500): Required<Contact>[] => {
48	  const nbAvailblePictures = 223;
49	  let numberOfContacts = 0;
50	
51	  return Array.from(Array(size).keys()).map((id) => {
52	    const has_avatar =
53	      weightedBoolean(25) && numberOfContacts < nbAvailblePictures;
54	    const gender = random.arrayElement(contactGender).value;
55	    const first_name = name.firstName(gender as any);
56	    const last_name = name.lastName();
57	    const email_jsonb = [
58	      {
59	        email: internet.email(first_name, last_name),
60	        type: getRandomContactDetailsType(),
61	      },
62	    ];
63	    const phone_jsonb = [
64	      {
65	        number: phone.phoneNumber(),
66	        type: getRandomContactDetailsType(),
67	      },
68	      {
69	        number: phone.phoneNumber(),
70	        type: getRandomContactDetailsType(),
71	      },
72	    ];
73	    const avatar = {
74	      src: has_avatar
75	        ? "https://marmelab.com/posters/avatar-" +
76	          (223 - numberOfContacts) +
77	          ".jpeg"
78	        : undefined,
79	    };
80	    const title = fakerCompany.bsAdjective();
81	
82	    if (has_avatar) {
83	      numberOfContacts++;
84	    }
85	
86	    // choose company with people left to know
87	    let company: Company;
88	    do {
89	      company = random.arrayElement(db.companies);
90	    } while ((company.nb_contacts ?? 0) >= maxContacts[company.size]);
91	    company.nb_contacts = (company.nb_contacts ?? 0) + 1;
92	
93	    // Force the first few contacts to have a recent `first_seen` so
94	    // the "New" badge is visible in demo mode. Older IDs still get a
95	    // random date in the company's history.
96	    const first_seen =
97	      id < NUMBER_OF_RECENT_CONTACTS
98	        ? randomRecentDate()
99	        : randomDate(new Date(company.created_at)).toISOString();
100	    const last_seen = first_seen;
101	
102	    return {
103	      id,
104	      first_name,
105	      last_name,
106	      gender,
107	      title: title.charAt(0).toUpperCase() + title.substr(1),
108	      company_id: company.id,
109	      company_name: company.name,
110	      email_jsonb,
111	      phone_jsonb,
112	      background: lorem.sentence(),
113	      acquisition: random.arrayElement(["inbound", "outbound"]),
114	      avatar,
115	      first_seen: first_seen,
116	      last_seen: last_seen,
117	      has_newsletter: weightedBoolean(30),
118	      status: random.arrayElement(defaultNoteStatuses).value,
119	      tags: random
120	        .arrayElements(db.tags, random.arrayElement([0, 0, 0, 1, 1, 2]))
121	        .map((tag) => tag.id), // finalize
122	      sales_id: company.sales_id!,
123	      nb_tasks: 0,
124	      linkedin_url: null,
125	    };
126	  });
127	};
