3	export const finalize = (db: Db) => {
4	  // set contact status according to the latest note
5	  db.contact_notes
6	    .sort((a, b) => new Date(a.date).valueOf() - new Date(b.date).valueOf())
7	    .forEach((note) => {
8	      db.contacts[note.contact_id as number].status = note.status;
9	    });
10	
11	  // Denormalize nb_notes onto each deal so the Kanban card can display a
12	  // note counter without running a separate query per card.
13	  // Initialize every deal to 0 first so deals with no notes still report a
14	  // known value (rather than undefined) while honoring the optional type.
15	  db.deals.forEach((deal) => {
16	    deal.nb_notes = 0;
17	  });
18	  db.deal_notes.forEach((note) => {
19	    const deal = db.deals[note.deal_id as number];
20	    if (deal) {
21	      deal.nb_notes = (deal.nb_notes ?? 0) + 1;
22	    }
23	  });
24	};
