+/**
+ * Returns `true` when the given ISO date string is a valid date less
+ * than {@link NEW_CONTACT_THRESHOLD_DAYS} days before `now`.
+ *
+ * Safe on `null`/`undefined`/malformed inputs — returns `false`.
+ */
+const isRecentFirstSeen = (
+  firstSeen: string | null | undefined,
+  now: number = Date.now(),
+): boolean => {
+  if (!firstSeen) return false;
+  const ts = Date.parse(firstSeen);
+  if (Number.isNaN(ts)) return false;
+  return now - ts < NEW_CONTACT_THRESHOLD_MS;
+};
