32	/**
33	 * Returns a random ISO date between `now - 7 days + 1 hour` (to stay
34	 * strictly within the "new" window) and `now`.
35	 */
36	const randomRecentDate = (): string => {
37	  const now = Date.now();
38	  // Stay at least 1 hour inside the window to avoid off-by-one flakiness.
39	  const minTs = now - SEVEN_DAYS_MS + 60 * 60 * 1000;
40	  const ts = minTs + Math.floor(Math.random() * (now - minTs));
41	  return new Date(ts).toISOString();
42	};
